NCXX1536.ol:
###########################################
# Calculate ENTRY_128_FSSXB from SGM dump #
###########################################

# Get the values of the two dump parameters
VAR_rawMSB := NCXY1536.raw; # 1 MSB Byte
VAR_rawLSB := NCXZ1536.raw; # 3 LSB Bytes

# Shift to be performed
VAR_MSB_SHIFT := 24;
VAR_LSB_MASK := 65535;

# Shift MSB value
VAR_MSB := (VAR_rawMSB << VAR_MSB_SHIFT);

# Recreate the dumped value by concatenating the results
VAR_RES := (VAR_MSB + VAR_rawLSB);

# If the value is all zeros, return it with decoding
if VAR_RES == 0 then
     return (0.0);
endif;


# Unfortunately loops are not supported in synthetics and a manual 
# calculation of all steps is required.

# Define some useful masks
VAR_SIGN_MASK := 4294967296;  # The sign bit (bit 31)
VAR_EXP_MASK := 2139095040;   # The exponent bits (bits 23 to 30) 
VAR_MANTISSA_MASK := 8388607; # The mantissa bits (bits  0 to 22)
VAR_BIT_MASK := 1; # A single bit mask

# Calculate the sign value
VAR_SIGN:= (VAR_RES and VAR_SIGN_MASK) >> 32;

# Calculate the exponent value
VAR_EXP := (VAR_RES and VAR_EXP_MASK) >> 23;

# Calculate the mantissa value
VAR_MANT := (VAR_RES and VAR_MANTISSA_MASK);

# To calculate the sum of on the last part of the equation, these manual 
# calculations are needed
VAR_IDX := 1;
VAR_RES_1 := (2**-VAR_IDX)*((VAR_MANT >> (23 - VAR_IDX)) and VAR_BIT_MASK);
VAR_IDX := 2;
VAR_RES_2 := (2**-VAR_IDX)*((VAR_MANT >> (23 - VAR_IDX)) and VAR_BIT_MASK);
VAR_IDX := 3;
VAR_RES_3 := (2**-VAR_IDX)*((VAR_MANT >> (23 - VAR_IDX)) and VAR_BIT_MASK);
VAR_IDX := 4;
VAR_RES_4 := (2**-VAR_IDX)*((VAR_MANT >> (23 - VAR_IDX)) and VAR_BIT_MASK);
VAR_IDX := 5;
VAR_RES_5 := (2**-VAR_IDX)*((VAR_MANT >> (23 - VAR_IDX)) and VAR_BIT_MASK);
VAR_IDX := 6;
VAR_RES_6 := (2**-VAR_IDX)*((VAR_MANT >> (23 - VAR_IDX)) and VAR_BIT_MASK);
VAR_IDX := 7;
VAR_RES_7 := (2**-VAR_IDX)*((VAR_MANT >> (23 - VAR_IDX)) and VAR_BIT_MASK);
VAR_IDX := 8;
VAR_RES_8 := (2**-VAR_IDX)*((VAR_MANT >> (23 - VAR_IDX)) and VAR_BIT_MASK);
VAR_IDX := 9;
VAR_RES_9 := (2**-VAR_IDX)*((VAR_MANT >> (23 - VAR_IDX)) and VAR_BIT_MASK);
VAR_IDX := 10;
VAR_RES_10 := (2**-VAR_IDX)*((VAR_MANT >> (23 - VAR_IDX)) and VAR_BIT_MASK);
VAR_IDX := 11;
VAR_RES_11 := (2**-VAR_IDX)*((VAR_MANT >> (23 - VAR_IDX)) and VAR_BIT_MASK);
VAR_IDX := 12;
VAR_RES_12 := (2**-VAR_IDX)*((VAR_MANT >> (23 - VAR_IDX)) and VAR_BIT_MASK);
VAR_IDX := 13;
VAR_RES_13 := (2**-VAR_IDX)*((VAR_MANT >> (23 - VAR_IDX)) and VAR_BIT_MASK);
VAR_IDX := 14;
VAR_RES_14 := (2**-VAR_IDX)*((VAR_MANT >> (23 - VAR_IDX)) and VAR_BIT_MASK);
VAR_IDX := 15;
VAR_RES_15 := (2**-VAR_IDX)*((VAR_MANT >> (23 - VAR_IDX)) and VAR_BIT_MASK);
VAR_IDX := 16;
VAR_RES_16 := (2**-VAR_IDX)*((VAR_MANT >> (23 - VAR_IDX)) and VAR_BIT_MASK);
VAR_IDX := 17;
VAR_RES_17 := (2**-VAR_IDX)*((VAR_MANT >> (23 - VAR_IDX)) and VAR_BIT_MASK);
VAR_IDX := 18;
VAR_RES_18 := (2**-VAR_IDX)*((VAR_MANT >> (23 - VAR_IDX)) and VAR_BIT_MASK);
VAR_IDX := 19;
VAR_RES_19 := (2**-VAR_IDX)*((VAR_MANT >> (23 - VAR_IDX)) and VAR_BIT_MASK);
VAR_IDX := 20;
VAR_RES_20 := (2**-VAR_IDX)*((VAR_MANT >> (23 - VAR_IDX)) and VAR_BIT_MASK);
VAR_IDX := 21;
VAR_RES_21 := (2**-VAR_IDX)*((VAR_MANT >> (23 - VAR_IDX)) and VAR_BIT_MASK);
VAR_IDX := 22;
VAR_RES_22 := (2**-VAR_IDX)*((VAR_MANT >> (23 - VAR_IDX)) and VAR_BIT_MASK);
VAR_IDX := 23;
VAR_RES_23 := (2**-VAR_IDX)*((VAR_MANT >> (23 - VAR_IDX)) and VAR_BIT_MASK);

# Calculate the sum
VAR_MANT_RES := 1.0 + VAR_RES_1 + VAR_RES_2 + VAR_RES_3 + VAR_RES_4 + VAR_RES_5 + VAR_RES_6 + VAR_RES_7 + VAR_RES_8 + VAR_RES_9 + VAR_RES_10 + VAR_RES_11 + VAR_RES_12 + VAR_RES_13 + VAR_RES_14 + VAR_RES_15 + VAR_RES_16 + VAR_RES_17 + VAR_RES_18 + VAR_RES_19 + VAR_RES_20 + VAR_RES_21 + VAR_RES_22 + VAR_RES_23;

# Return the final result
return ((-1)**VAR_SIGN * 2**(VAR_EXP - 127)*VAR_MANT_RES);

NPWSX035.ol:
###################################################################################################
#
# Characterize double EDAC errors in the PCDU B EEPROM memory for Reconfiguration Table 2
#
#  Description: The PCDU raises the REC1 EDAC double error flag whenever it passes through 
#               uninitialised memory as per SOL.CRS.UM.00020, section 6.3.5
#
#               If non-initialized memory areas are read using SA28T, EDAC flags will indicate 
#               simple or double error. This is because EDAC information has not been stored in 
#               memory.
#
#               This synthetic also checks the checked address against the defined ranges and
#               sets accordingly the result value so that only in meaningful cases an alarm is
#               raised.
#
#               The defined memory ranges are as follows
#                  Reconfiguration Table #1: 0x4000 to 0x4100 (16384 to 16640) 
#                  Reconfiguration Table #2: 0x4100 to 0x4200 (16640 to 16896) 
#                  Reconfiguration Table #3: 0x4200 to 0x4300 (16896 to 17152) 
#                  Reconfiguration Table #4: 0x4300 to 0x4400 (17152 to 17408) 
#                                Empty Area: 0x4400 to 0x8000 (17408 to 32768) 
#
#  Return values: The following values are returned
#                    If NPWT0798 == OK then 0 is returned
#                    If NPWT0798 == NOK and NPWT6502 in the Reconfiguration Table #2 range then 1 is returned
#                    If NPWT0798 == NOK and NPWT6502 in any other range then 0 is returned
#                               
###################################################################################################


# Define the memory ranges
VAR_REC_1_START := 16384;
VAR_REC_1_END := 16640;
VAR_REC_2_START := 16640;
VAR_REC_2_END := 16896;
VAR_REC_3_START := 16896;
VAR_REC_3_END := 17152;
VAR_REC_4_START := 17152;
VAR_REC_4_END := 17408;
VAR_EMPTY_START := 17408;
VAR_EMPTY_END := 32768;


# Double EDAC error detected in EEPROM Reconfiguration Table 2
if (NPWT0798.eng == "NOK") then

  # Check if the error address is in the Reconfiguration Table 1 range
  if ((NPWT6502.raw >= VAR_REC_1_START) land (NPWT6502.raw < VAR_REC_1_END)) then
	 # Return the OK code as this is not the reconfiguration table corresponding to the parameter
     return(0);
  endif;

  # Check if the error address is in the Reconfiguration Table 2 range
  if ((NPWT6502.raw >= VAR_REC_2_START) land (NPWT6502.raw < VAR_REC_2_END)) then
     # Return the NOK code for the reconfiguration table #2
     return(1);
  endif;

  # Check if the error address is in the Reconfiguration Table 3 range
  if ((NPWT6502.raw >= VAR_REC_3_START) land (NPWT6502.raw < VAR_REC_3_END)) then
     # Return the OK code as this is not the reconfiguration table corresponding to the parameter
     return(0);
  endif;

  # Check if the error address is in the Reconfiguration Table 4 range
  if ((NPWT6502.raw >= VAR_REC_4_START) land (NPWT6502.raw < VAR_REC_4_END)) then
     # Return the OK code as this is not the reconfiguration table corresponding to the parameter
     return(0);
  endif;

else
     # No error detected
     return(0);
endif;
